420	\begin{lemma}[Preservation of the robustness error family]\label{lem:qld-extraction-error-form}
421		\lean{MIPStarRE.QPBT.deltaExtract_le_deltaQld}
422		\uses{def:admissible, lem:qld-unitary}
423		Let $C\geq1$, $a>1$, and $0<b<1$. Suppose that
424		\[
425			\delta_G=a(md)^a\bigl(\eps^b+q^{-b}+2^{-bmd}\bigr),
426			\qquad
427			\delta_P=C\left(\delta_G+\sqrt{\eps}+\frac{md}{q}\right),
428		\]
429		and set $\delta_{\mathrm{ext}}=C(\delta_P^{1/4}+md/q)$. There are constants
430		$a'\geq1$ and $0<b'<1$, depending only on $C,a,b$, such that, for every
